export const servicePractices: ServicePractice[] = [corporateCommercial, regulatoryServices, litigationDisputeResolution, businessAdvisoryConsulting, licensingRegistrations, intellectualProperty, femaFdiCrossBorder, taxationCompliance, bankingRbiFinancialServices];
export function resolvePractice(slugs: string[]) {
  if (slugs.length > 2) return null;
  const practice = servicePractices.find(item => item.slug === slugs[0]);
  if (!practice) return null;
  const group = slugs.length === 2 ? practice.groups.find(item => item.slug === slugs[1]) : undefined;
  if (slugs.length === 2 && !group) return null;
  return {practice, group};
}
